using System;using System.IO;using System.Linq;using System.Runtime.InteropServices;using System.Web.Script.Serialization;using interop.ICApiIronCAD;namespace RockPro{public static class LatchInProcess{public static int Run(string folder){dynamic l=Marshal.GetActiveObject("IronCAD.Application");var a=(IZBaseApp)l.ZIronCADApp;var s=(IZSceneDoc)a.ActiveDoc;var mgr=s.ParameterMgr;File.WriteAllText(Path.Combine(folder,"result.json"),new JavaScriptSerializer().Serialize(new{passed=true,parameters=Enumerable.Range(0,mgr.Count).Select(i=>mgr.GetParameter(i)).Select(p=>new{name=p.Name,expression=p.Expression,value=p.Type==eZParamType.Z_PARAMETER_TYPE_TEXT?0:p.Value}).ToArray()}));return 0;}}}